    devmgr: '<rect x="10" y="10" width="200" height="130" fill="#fff" stroke="#000"/><g font-size="7" font-family="Tahoma"><text x="20" y="26">+ CDROM</text><text x="20" y="38">+ Disk drives</text><text x="20" y="50">+ Display adapters</text><text x="20" y="62">- Other devices</text><text x="34" y="74" fill="#000">! Hyperdrive Motivator</text><text x="34" y="86">! Bug Detector</text><text x="34" y="98">x PCI Toaster</text><text x="20" y="110">+ Sound, video and game</text><text x="20" y="122">+ Universal Serial Bus</text></g><circle cx="30" cy="72" r="4" fill="#ffd400" stroke="#000" class="sys-dz-bang"/><circle cx="30" cy="84" r="4" fill="#ffd400" stroke="#000"/>',
